#include "client.h"
#define NO(t) (cp(out,cap,L##t),0)
static int unc(W*out,int n,const Endpoint*e,T share){return validend(e)&&cp(out,n,L"\\\\")&&cat(out,n,e->ip)&&cat(out,n,L"\\")&&cat(out,n,share);}
static int valname(W*out,T letter){if(!letterok(letter))return 0;cp(out,12,L"Drive-");out[6]=letter[0]&~32;out[7]=0;return 1;}
static int credname(W*out,int n,const Endpoint*ep,T name){W inv[320];return invite(inv,CNT(inv),ep->host,ep->ip,ep->machine)&&cp(out,n,L"ChaZeumNAS5/")&&cat(out,n,inv)&&cat(out,n,L"/")&&cat(out,n,name);}
static int savepass(T name,T user,T pass){Cred c={0};c.type=1;c.target=(W*)name;c.user=(W*)user;c.persist=2;c.bytes=2*sz(pass);c.blob=(U8*)pass;return CredWriteW(&c,0);}
static int retrieve(T name,T user,W*out,int cap){Cred*c=0;out[0]=0;if(!CredReadW(name,1,0,&c))return 0;int valid=c->blob&&c->bytes>0&&c->bytes%2==0&&c->bytes<(U32)cap*2&&eq(c->user,user);if(valid){memcpy(out,c->blob,c->bytes);out[c->bytes/2]=0;}if(c->blob)erase(c->blob,c->bytes);CredFree(c);return valid;}
int getmap(T letter,W*out,int cap){W vn[12];return valname(vn,letter)&&getstr(HKCU,CLIKEY,vn,out,cap);}
static int parsemap(const Endpoint*ep,W*info,W**share,W**user){W*x=0,*y=0;for(W*p=info;*p;p++)if(*p=='|'){x=y;y=p;}if(!x||!y)return 0;*y=0;*x=0;*share=x+1;*user=y+1;Endpoint native;return pair(info,native.host,native.ip,native.machine)&&eq(ep->host,native.host)&&eq(ep->ip,native.ip)&&eq(ep->machine,native.machine)&&shareok(*share)&&idok(*user);}
static int dircan(T path){H h=CreateFileW(path,1,7,0,3,0x02000000,0);if(h==BAD)return 0;CloseHandle(h);return 1;}
/* A normal SMB session may reuse an earlier login and ignore a newly typed
   password. Use an independent outbound logon for proof and enumeration.
   LogonUser(NEW_CREDENTIALS) alone does NOT validate the remote password. */
static int authbegin(const Endpoint*ep,T id,T pass,H*token,W*out,int cap){
*token=0;if(!validend(ep)||!idok(id)||!sz(pass)||sz(pass)>256)return NO("NAS 아이디와 암호를 확인하세요.");
if(!LogonUserW(id,ep->machine,pass,9,3,token))return errnum(out,cap,L"독립된 NAS 로그인 검사를 시작하지 못했습니다.",GetLastError());
if(!ImpersonateLoggedOnUser(*token)){U32 e=GetLastError();CloseHandle(*token);*token=0;return errnum(out,cap,L"NAS 로그인 검사 준비에 실패했습니다. 기존 연결은 유지했습니다.",e);}return 1;}
static void authend(H token){
/* Never perform registry, drive or credential writes while impersonating. */
if(!RevertToSelf()){CloseHandle(token);ExitProcess(5);}CloseHandle(token);}
static int prove(const Endpoint*ep,T id,T pass,T path,W*out,int cap){H token=0;if(!authbegin(ep,id,pass,&token,out,cap))return 0;
int ok=dircan(path);U32 e=ok?0:GetLastError();authend(token);if(!ok)return errnum(out,cap,L"입력한 아이디·암호로 폴더를 열지 못했습니다. 암호와 폴더 권한을 확인하세요. 기존 저장된 암호는 바꾸지 않았습니다.",e);return 1;}
static U32 add(T drive,T dest,T user,T pass){Resource r={0};r.type=drive?1:0;r.local=(W*)drive;r.remote=(W*)dest;return WNetAddConnection2W(&r,pass,user,0);}
static int tag(T p){T h=L"ChaZeumNAS5:";if(sz(p)!=44)return 0;for(int i=0;i<12;i++)if(p[i]!=h[i])return 0;for(int i=12;i<44;i++)if(!((p[i]>='0'&&p[i]<='9')||(p[i]>='a'&&p[i]<='f')))return 0;return 1;}
int scanonly(const Endpoint*ep,T id,T pass,W*out,int cap){W resource[110],ipc[110],acct[80],server[40];H token=0;Share1*v=0;U32 n=0,total=0,resume=0,e=0;int connected=0,okay=0,found=0;
if(!idok(id)||!sz(pass)||!unc(ipc,CNT(ipc),ep,L"IPC$"))return NO("NAS 아이디와 암호를 입력하세요.");
if(!authbegin(ep,id,pass,&token,out,cap))return 0;_snwprintf(acct,CNT(acct),L"%ls\\%ls",ep->machine,id);e=add(0,ipc,acct,pass);
if(e){errnum(out,cap,L"폴더 목록 로그인 실패. NAS 아이디·암호를 확인하세요.",e);goto done;}connected=1;
_snwprintf(server,CNT(server),L"\\\\%ls",ep->ip);cp(out,cap,L"이 아이디로 열 수 있는 폴더:\r\n");
do{e=NetShareEnum(server,1,(U8**)&v,0xffffffff,&n,&total,&resume);if(e&&e!=234){errnum(out,cap,L"폴더 조회 실패",e);goto done;}
for(U32 i=0;i<n;i++)if(v[i].type==0&&shareok(v[i].name)&&tag(v[i].remark)&&unc(resource,CNT(resource),ep,v[i].name)&&dircan(resource)){cat(out,cap,L" • ");cat(out,cap,v[i].name);cat(out,cap,L"\r\n");found++;}
if(v)NetApiBufferFree(v);v=0;}while(e==234);if(!found)cat(out,cap,L"없음. 서버에서 이 아이디에 해당 폴더의 권한을 주세요.");okay=1;
done:if(v)NetApiBufferFree(v);if(connected){U32 cleanup=WNetCancelConnection2W(ipc,0,0);if(cleanup&&cleanup!=2250){errnum(out,cap,L"목록 조회용 임시 접속의 정리를 확인하지 못했습니다.",cleanup);okay=0;}}
authend(token);return okay;}
int mapdrive(const Endpoint*ep,T share,T id,T letter,W*pass,int remember,W*out,int cap){W remote[130],acct[80],old[350],vn[12],ct[390],profile[460];if(!valname(vn,letter)||!shareok(share)||!idok(id)||!pass||!sz(pass)||sz(pass)>256||!unc(remote,CNT(remote),ep,share))return NO("공유 이름·NAS 아이디·암호·빈 드라이브 문자를 확인하세요.");_snwprintf(acct,CNT(acct),L"%ls\\%ls",ep->machine,id);if(!credname(ct,CNT(ct),ep,vn))return 0;U32 c=CNT(old),lookup=WNetGetConnectionW(letter,old,&c);int existed=!lookup;if(existed&&!eq(old,remote))return NO("선택한 문자는 다른 드라이브가 사용 중입니다. 다른 문자를 고르세요.");if(!existed&&((GetLogicalDrives()>>( (letter[0]&~32)-'A'))&1))return NO("이미 사용 중인 드라이브 문자입니다. 기존 드라이브는 변경하지 않았습니다.");if(!existed&&lookup!=2250&&lookup!=1200)return errnum(out,cap,L"드라이브의 기존 연결을 확인하지 못했습니다.",lookup);
if(existed){extern U32 WNetGetUserW(T,W*,U32*);W who[300];U32 n=CNT(who);if(WNetGetUserW(letter,who,&n)||!eq(acct,who))return NO("기존 연결의 로그인 아이디가 다르거나 확인되지 않았습니다. 연결을 바꾸지 않았습니다.");}
if(remember&&!prove(ep,id,pass,remote,out,cap))return 0;
if(!existed){U32 e=add(letter,remote,acct,pass);if(e)return errnum(out,cap,L"드라이브 연결 실패. 5는 권한, 86은 암호, 1219는 다른 계정 연결을 확인하세요.",e);}if(!dircan(remote)){if(!existed)WNetCancelConnection2W(letter,0,0);return NO("공유 폴더를 실제로 열지 못해 연결을 저장하지 않았습니다.");}
if(remember){if(!invite(profile,CNT(profile),ep->host,ep->ip,ep->machine)||!cat(profile,CNT(profile),L"|")||!cat(profile,CNT(profile),share)||!cat(profile,CNT(profile),L"|")||!cat(profile,CNT(profile),id)||!savepass(ct,acct,pass)||!putstr(HKCU,CLIKEY,vn,profile))return NO("지금 연결됐지만 자동 재연결 정보를 전부 저장하지 못했습니다.");}_snwprintf(out,cap,L"%ls 에 연결했습니다. 파일 탐색기 → 내 PC에서 열 수 있습니다.",letter);return 1;}
int detach(T letter,W*out,int cap){Endpoint ep;W info[460],remote[130],other[300],vn[12],ct[390],*sh,*id;if(!loadendpoint(HKCU,CLIKEY,&ep)||!getmap(letter,info,CNT(info))||!parsemap(&ep,info,&sh,&id)||!valname(vn,letter)||!unc(remote,CNT(remote),&ep,sh))return NO("이 앱에 저장된 드라이브 문자를 선택하세요.");U32 n=CNT(other),e=WNetGetConnectionW(letter,other,&n);if(!e){if(!eq(other,remote))return NO("이 문자가 현재 다른 곳을 가리켜 해제하지 않았습니다.");W who[300],acct[80];n=CNT(who);_snwprintf(acct,CNT(acct),L"%ls\\%ls",ep.machine,id);if(WNetGetUserW(letter,who,&n)||!eq(who,acct))return NO("현재 연결의 아이디가 저장된 아이디와 다르거나 확인되지 않아 해제하지 않았습니다.");e=WNetCancelConnection2W(letter,0,0);if(e)return errnum(out,cap,L"사용 중인 파일을 닫은 뒤 다시 시도하세요.",e);}else if(e!=2250&&e!=1200)return errnum(out,cap,L"드라이브 상태 확인 실패",e);
if(credname(ct,CNT(ct),&ep,vn))CredDeleteW(ct,1,0);if(!delstr(HKCU,CLIKEY,vn))return NO("연결은 해제됐지만 재연결 설정 정리에 실패했습니다.");return cp(out,cap,L"이 앱의 드라이브 연결과 저장된 로그인을 제거했습니다.");}
int restore(W*out,int cap){Endpoint e;W inf[460],v[12],ct[390],wh[80],pass[257],one[500],letter[]={L'A',L':',0};int saved=0,good=0;out[0]=0;if(!loadendpoint(HKCU,CLIKEY,&e))return NO("저장된 서버 정보가 없습니다.");for(int i=0;i<26;i++){letter[0]='A'+i;if(getmap(letter,inf,CNT(inf)))saved++;}if(!saved)return NO("재연결할 드라이브를 먼저 저장하세요.");if(!connectnas(&e,0,one,CNT(one))){cp(out,cap,one);return 0;}for(int i=0;i<26;i++){W*sh,*id;letter[0]='A'+i;if(!getmap(letter,inf,CNT(inf))||!parsemap(&e,inf,&sh,&id))continue;valname(v,letter);credname(ct,CNT(ct),&e,v);_snwprintf(wh,CNT(wh),L"%ls\\%ls",e.machine,id);if(!retrieve(ct,wh,pass,CNT(pass))){cat(out,cap,letter);cat(out,cap,L" 저장된 로그인 없음\r\n");continue;}int ok=mapdrive(&e,sh,id,letter,pass,0,one,CNT(one));erase(pass,sizeof(pass));good+=ok;cat(out,cap,letter);cat(out,cap,L" ");cat(out,cap,one);cat(out,cap,L"\r\n");}return good==saved;}
extern I32 SHGetFolderPathW(H,I32,H,U32,W*),CreateDirectoryW(T,Security*),CopyFileW(T,T,I32);
int setstartup(int enable,W*out,int cap){T run=L"Software\\Microsoft\\Windows\\CurrentVersion\\Run";T name=L"ChaZeumNAS5";W f[1024],home[512],line[1100],current[1100],prev[1024];int old=getstr(HKCU,run,name,current,CNT(current));int had=getstr(HKCU,CLIKEY,L"StartupCopy",prev,CNT(prev));if(old){if(!had)return NO("같은 이름의 기존 자동 시작 항목이 있어 변경하지 않았습니다.");_snwprintf(line,CNT(line),L"\"%ls\" /reconnect",prev);if(!eq(line,current))return NO("기존 자동 시작 항목의 소유를 확인할 수 없습니다.");}if(!enable){if(!delstr(HKCU,run,name))return NO("자동 시작을 해제하지 못했습니다.");return cp(out,cap,L"다음 로그인부터 자동 연결을 시작하지 않습니다.");}if(old)return cp(out,cap,L"로그인 시 자동 연결이 이미 켜져 있습니다.");U32 l=GetModuleFileNameW(0,f,CNT(f));if(!l||l>=CNT(f)||SHGetFolderPathW(0,0x1c,0,0,home)||!cat(home,CNT(home),L"\\ChaZeumNAS5"))return NO("개인 앱 폴더를 찾을 수 없습니다.");if(!CreateDirectoryW(home,0)&&GetLastError()!=183)return NO("개인 앱 폴더를 만들 수 없습니다.");W id[34];if(!guidtext(id,CNT(id))||!cat(home,CNT(home),L"\\Client-")||!cat(home,CNT(home),id)||!cat(home,CNT(home),L".exe")||!CopyFileW(f,home,1))return NO("자동 연결에 쓸 유저용 복사본을 만들지 못했습니다.");_snwprintf(line,CNT(line),L"\"%ls\" /reconnect",home);if(!putstr(HKCU,CLIKEY,L"StartupCopy",home)||!putstr(HKCU,run,name,line)){DeleteFileW(home);return NO("Windows 자동 시작을 등록하지 못했습니다.");}return cp(out,cap,L"다음 Windows 로그인 때 이 앱이 VPN과 저장한 드라이브를 자동 연결합니다.");}
